    ('config', 'from_dict_ignores_unknown_keys', 'tests/test_config.py', 'import mdgan.config as mod\nfrom dataclasses import fields as _fields\n_orig = mod.Config.from_dict.__func__\ndef from_dict(cls, d):\n    known = {f.name for f in _fields(cls)}\n    return _orig(cls, {k: v for k, v in d.items() if k in known})     # silently drops stale keys\nmod.Config.from_dict = classmethod(from_dict)'),
    ('config', 'estimation_blocks_rounds_down', 'tests/test_config.py', 'import mdgan.config as mod\ndef estimation_blocks(self, dt_fine_ps):\n    return int(self.estimation_time_ps / (dt_fine_ps * self.step_skip) // self.block_len)\nmod.Config.estimation_blocks = estimation_blocks'),
