    # --- losses ------------------------------------------------------------------------------
    ('losses', 'eps_shared_across_batch', 'tests/test_losses.py', 'import mdgan.losses as mod\nimport torch as _t\ndef gradient_penalty(critic, real, fake, gp_lambda=10.0, generator=None):\n    eps = _t.rand(1, 1, 1, generator=generator)                         # one eps for the whole batch\n    x = (eps * real.detach() + (1 - eps) * fake.detach()).requires_grad_(True)\n    g, = _t.autograd.grad(critic(x).sum(), x, create_graph=True)\n    n = g.flatten(1).norm(dim=1)\n    return gp_lambda * ((n - 1) ** 2).mean(), n.detach()\nmod.gradient_penalty = gradient_penalty'),
    ('losses', 'penalty_on_squared_norm', 'tests/test_losses.py', 'import mdgan.losses as mod\n_orig = mod.gradient_penalty\ndef gradient_penalty(critic, real, fake, gp_lambda=10.0, generator=None):\n    gp, n = _orig(critic, real, fake, gp_lambda, generator)\n    import torch as _t\n    eps = _t.rand(real.shape[0], 1, 1, generator=generator)\n    x = (eps * real.detach() + (1 - eps) * fake.detach()).requires_grad_(True)\n    g, = _t.autograd.grad(critic(x).sum(), x, create_graph=True)\n    sq = (g.flatten(1) ** 2).sum(1)                                       # ||g||^2 instead of ||g||\n    return gp_lambda * ((sq - 1) ** 2).mean(), n\nmod.gradient_penalty = gradient_penalty'),
    ('losses', 'no_create_graph', 'tests/test_losses.py', 'import mdgan.losses as mod\nimport torch as _t\ndef gradient_penalty(critic, real, fake, gp_lambda=10.0, generator=None):\n    eps = _t.rand(real.shape[0], 1, 1, generator=generator)\n    x = (eps * real.detach() + (1 - eps) * fake.detach()).requires_grad_(True)\n    g, = _t.autograd.grad(critic(x).sum(), x)                            # penalty cannot train the critic\n    n = g.flatten(1).norm(dim=1)\n    return gp_lambda * ((n - 1) ** 2).mean(), n.detach()\nmod.gradient_penalty = gradient_penalty'),
    ('losses', 'lambda_ignored', 'tests/test_losses.py', 'import mdgan.losses as mod\n_orig = mod.gradient_penalty\nmod.gradient_penalty = lambda critic, real, fake, gp_lambda=10.0, generator=None: _orig(critic, real, fake, 10.0, generator)'),
    ('losses', 'critic_sign_flipped', 'tests/test_losses.py', 'import mdgan.losses as mod\n_orig = mod.critic_loss\ndef critic_loss(critic, real, fake, gp_lambda=10.0, generator=None):\n    return _orig(critic, fake, real, gp_lambda, generator)               # real and fake swapped\nmod.critic_loss = critic_loss'),
    ('losses', 'critic_loss_keeps_fake_graph', 'tests/test_losses.py', 'import mdgan.losses as mod\ndef critic_loss(critic, real, fake, gp_lambda=10.0, generator=None):\n    d_real, d_fake = critic(real).mean(), critic(fake).mean()          # no detach on fake\n    gp, n = mod.gradient_penalty(critic, real, fake, gp_lambda, generator)\n    return d_fake - d_real + gp, {"wasserstein": (d_real - d_fake).detach(), "gradient_penalty": gp.detach(),\n                                  "grad_norm": n.mean()}\nmod.critic_loss = critic_loss'),
    ('losses', 'penalty_reaches_generators', 'tests/test_losses.py', 'import mdgan.losses as mod\nimport torch as _t\ndef gradient_penalty(critic, real, fake, gp_lambda=10.0, generator=None):\n    eps = _t.rand(real.shape[0], 1, 1, generator=generator)\n    x = eps * real + (1 - eps) * fake                                    # no detach: gradient leaks to G\n    if not x.requires_grad:\n        x = x.requires_grad_(True)\n    g, = _t.autograd.grad(critic(x).sum(), x, create_graph=True)\n    n = g.flatten(1).norm(dim=1)\n    return gp_lambda * ((n - 1) ** 2).mean(), n.detach()\nmod.gradient_penalty = gradient_penalty'),
    ('losses', 'generator_sign_flipped', 'tests/test_losses.py', 'import mdgan.losses as mod\nmod.generator_loss = lambda critic, fake: critic(fake).mean()'),
    # --- rollout -----------------------------------------------------------------------------
    ('rollout', 'fake_window_pair_not_consecutive', 'tests/test_rollout.py', 'import mdgan.rollout as mod\nimport torch as _t\ndef make_fake_window(gz, gy, batch, burn_in, pair_window, *, mean_operation=True, generator=None):\n    j = int(_t.randint(burn_in, burn_in + pair_window, (1,), generator=generator))\n    z0 = _t.rand(batch, gz.latent_dim, generator=generator)\n    states = gz.unroll(z0, j + 2, generator=generator)\n    w = _t.cat([gy.generate(states[j], generator=generator), gy.generate(states[j + 2], generator=generator)], dim=1)\n    return mod._center(w) if mean_operation else w\nmod.make_fake_window = make_fake_window'),
    ('rollout', 'fake_window_j_below_burn_in', 'tests/test_rollout.py', 'import mdgan.rollout as mod\nimport torch as _t\ndef make_fake_window(gz, gy, batch, burn_in, pair_window, *, mean_operation=True, generator=None):\n    j = int(_t.randint(0, pair_window, (1,), generator=generator))\n    z0 = _t.rand(batch, gz.latent_dim, generator=generator)\n    states = gz.unroll(z0, j + 1, generator=generator)\n    w = _t.cat([gy.generate(states[j], generator=generator), gy.generate(states[j + 1], generator=generator)], dim=1)\n    return mod._center(w) if mean_operation else w\nmod.make_fake_window = make_fake_window'),
    ('rollout', 'fake_window_fixed_j', 'tests/test_rollout.py', 'import mdgan.rollout as mod\nimport torch as _t\ndef make_fake_window(gz, gy, batch, burn_in, pair_window, *, mean_operation=True, generator=None):\n    j = (int(_t.randint(burn_in, burn_in + pair_window, (1,), generator=generator)), burn_in)[1]\n    z0 = _t.rand(batch, gz.latent_dim, generator=generator)\n    states = gz.unroll(z0, j + 1, generator=generator)\n    w = _t.cat([gy.generate(states[j], generator=generator), gy.generate(states[j + 1], generator=generator)], dim=1)\n    return mod._center(w) if mean_operation else w\nmod.make_fake_window = make_fake_window'),
    ('rollout', 'fake_window_ignores_mean_flag', 'tests/test_rollout.py', 'import mdgan.rollout as mod\nimport torch as _t\ndef make_fake_window(gz, gy, batch, burn_in, pair_window, *, mean_operation=True, generator=None):\n    j = int(_t.randint(burn_in, burn_in + pair_window, (1,), generator=generator))\n    z0 = _t.rand(batch, gz.latent_dim, generator=generator)\n    states = gz.unroll(z0, j + 1, generator=generator)\n    w = _t.cat([gy.generate(states[j], generator=generator), gy.generate(states[j + 1], generator=generator)], dim=1)\n    return mod._center(w)\nmod.make_fake_window = make_fake_window'),
    ('rollout', 'rollout_skips_burn_in', 'tests/test_rollout.py', 'import mdgan.rollout as mod\nimport torch as _t\n@_t.no_grad()\ndef rollout(gz, gy, n_chains, n_blocks, burn_in, *, mean_operation=True, generator=None):\n    mod.positive_int("n_chains", n_chains); mod.positive_int("n_blocks", n_blocks)\n    out = _t.empty(n_chains, n_blocks * gy.block_len, gy.n_channels)\n    with mod._eval_mode(gz, gy):\n        z = _t.rand(n_chains, gz.latent_dim, generator=generator)\n        r_fixed = gz.sample_noise(n_chains, generator=generator)\n        for _ in range(0):\n            z = gz(z, gz.sample_noise(n_chains, generator=generator))\n        for k in range(n_blocks):\n            y = gy.generate(z, generator=generator)\n            if mean_operation:\n                y = mod._center(y)\n            out[:, k * gy.block_len:(k + 1) * gy.block_len] = y\n            if k + 1 < n_blocks:\n                z = gz(z, gz.sample_noise(n_chains, generator=generator))\n    return out\nmod.rollout = rollout'),
    ('rollout', 'rollout_ignores_mean_flag', 'tests/test_rollout.py', 'import mdgan.rollout as mod\nimport torch as _t\n@_t.no_grad()\ndef rollout(gz, gy, n_chains, n_blocks, burn_in, *, mean_operation=True, generator=None):\n    mod.positive_int("n_chains", n_chains); mod.positive_int("n_blocks", n_blocks)\n    out = _t.empty(n_chains, n_blocks * gy.block_len, gy.n_channels)\n    with mod._eval_mode(gz, gy):\n        z = _t.rand(n_chains, gz.latent_dim, generator=generator)\n        r_fixed = gz.sample_noise(n_chains, generator=generator)\n        for _ in range(burn_in):\n            z = gz(z, gz.sample_noise(n_chains, generator=generator))\n        for k in range(n_blocks):\n            y = gy.generate(z, generator=generator)\n            if False:\n                y = mod._center(y)\n            out[:, k * gy.block_len:(k + 1) * gy.block_len] = y\n            if k + 1 < n_blocks:\n                z = gz(z, gz.sample_noise(n_chains, generator=generator))\n    return out\nmod.rollout = rollout'),
    ('rollout', 'rollout_transition_before_decode', 'tests/test_rollout.py', 'import mdgan.rollout as mod\nimport torch as _t\n@_t.no_grad()\ndef rollout(gz, gy, n_chains, n_blocks, burn_in, *, mean_operation=True, generator=None):\n    mod.positive_int("n_chains", n_chains); mod.positive_int("n_blocks", n_blocks)\n    out = _t.empty(n_chains, n_blocks * gy.block_len, gy.n_channels)\n    with mod._eval_mode(gz, gy):\n        z = _t.rand(n_chains, gz.latent_dim, generator=generator)\n        r_fixed = gz.sample_noise(n_chains, generator=generator)\n        for _ in range(burn_in):\n            z = gz(z, gz.sample_noise(n_chains, generator=generator))\n        for k in range(n_blocks):\n            z = gz(z, gz.sample_noise(n_chains, generator=generator))\n            y = gy.generate(z, generator=generator)\n            if mean_operation:\n                y = mod._center(y)\n            out[:, k * gy.block_len:(k + 1) * gy.block_len] = y\n            if False:\n                z = gz(z, gz.sample_noise(n_chains, generator=generator))\n    return out\nmod.rollout = rollout'),
    ('rollout', 'rollout_reuses_noise', 'tests/test_rollout.py', 'import mdgan.rollout as mod\nimport torch as _t\n@_t.no_grad()\ndef rollout(gz, gy, n_chains, n_blocks, burn_in, *, mean_operation=True, generator=None):\n    mod.positive_int("n_chains", n_chains); mod.positive_int("n_blocks", n_blocks)\n    out = _t.empty(n_chains, n_blocks * gy.block_len, gy.n_channels)\n    with mod._eval_mode(gz, gy):\n        z = _t.rand(n_chains, gz.latent_dim, generator=generator)\n        r_fixed = gz.sample_noise(n_chains, generator=generator)\n        for _ in range(burn_in):\n            z = gz(z, r_fixed)\n        for k in range(n_blocks):\n            y = gy.generate(z, generator=generator)\n            if mean_operation:\n                y = mod._center(y)\n            out[:, k * gy.block_len:(k + 1) * gy.block_len] = y\n            if k + 1 < n_blocks:\n                z = gz(z, r_fixed)\n    return out\nmod.rollout = rollout'),
